theorem centerOneCoeff_ne_zero_of_good
    {b : R}
    (hb : CenterOneGoodB b)
    {k : Fin 9}
    (hk : k ≠ 4) :
    centerOneCoeff b k ≠ 0

theorem firstBlock_degree_budget {q m k : ℕ}
    (hm : 0 < m) (hk : 0 < k) (hkq : k ≤ q / m) :
    m * (q / m - k) + (m - 1) * k < q

theorem eval_geometricPolynomial_eq_zero {m : ℕ} {a : F}
    (ha : a ^ m = 1) (ha1 : a ≠ 1) :
    eval a (geometricPolynomial (F := F) m) = 0

theorem eval_stepanovG_of_eval_eq_zero {m : ℕ}
    (hmq : m ∣ Fintype.card F - 1) (f : Polynomial F) (c : F)
    (hc : eval c f = 0) : eval c (stepanovG m f) = 0

theorem eval_stepanovG_pow {m : ℕ}
    (hmq : m ∣ Fintype.card F - 1) (f : Polynomial F) (c : F)
    (hc : eval c f ≠ 0) : (eval c (stepanovG m f)) ^ m = 1

theorem stepanovT0_disjoint_T1 {m : ℕ}
    (hmq : m ∣ Fintype.card F - 1) (f : Polynomial F) :
    Disjoint (stepanovT0 f) (stepanovT1 m f)

theorem stepanovT1_disjoint_T2 {m : ℕ}
    (hmq : m ∣ Fintype.card F - 1) (f : Polynomial F) :
    Disjoint (stepanovT1 m f) (stepanovT2 m f)

theorem stepanovT_union {m : ℕ}
    (hmq : m ∣ Fintype.card F - 1) (f : Polynomial F) :
    (stepanovT0 f ∪ stepanovT1 m f) ∪ stepanovT2 m f = Finset.univ

theorem BlockRelation.blockTranslate {m : ℕ} {g : Polynomial F}
    {E : Fin m → Polynomial (Polynomial F)}
    (hrel : BlockRelation (Fintype.card F) g E) (c : F) :
    BlockRelation (Fintype.card F) (Polynomial.taylor c g)
      (fun i => blockTranslate c (E i))

theorem coeffNatDegreeLE_blockTranslate {D : ℕ}
    {E : Polynomial (Polynomial F)} (hE : CoeffNatDegreeLE D E) (c : F) :
    CoeffNatDegreeLE D (blockTranslate c E)

theorem coeffNatDegreeLE_taylor_constant {D : ℕ}
    {E : Polynomial (Polynomial F)} (hE : CoeffNatDegreeLE D E) (c : F) :
    CoeffNatDegreeLE D (Polynomial.taylor (C c) E)

theorem kummerAbsolutelyIrreducible_of_simple_root
    {m : ℕ} (hm : 0 < m) {f : Polynomial F} {a : F}
    (ha : f.rootMultiplicity a = 1) : KummerAbsolutelyIrreducible m f

theorem kummerPolynomial_irreducible_of_simple_root
    {m : ℕ} (hm : 0 < m) {f : Polynomial F} {a : F}
    (ha : f.rootMultiplicity a = 1) : Irreducible (kummerPolynomial m f)

theorem exists_monic_rescale {r n : ℕ} (roots : Fin r → F)
    (hinj : Function.Injective roots) (hn : r ≤ n) (j : Fin r) (u : Fˣ) :
    ∃ e : (Fin n → F) ≃ (Fin n → F), ∀ v i,
      (monicOfCoeffs n (e v)).eval (roots i) =
        if i = j then (u : F) * (monicOfCoeffs n v).eval (roots i)
        else (monicOfCoeffs n v).eval (roots i)

theorem avoidingSeries_coeff_eq_zero (w : Polynomial F → ℂ) {n k : ℕ}
    (hk : 0 < k) (hkn : k ≤ n) :
    PowerSeries.coeff k (avoidingSeries w (monicIrreduciblesThrough n)) = 0

theorem centerZeroPowerWeight_le_at_zero {n d : ℕ} (hd : 0 < d) {x : F}
    (hx : x = -1 ∨ x = 0 ∨ x = 1) :
    centerZeroPowerWeight n d x ≤ (d : ℝ) ^ 2

theorem map_isMagicOfPowers [CommRing R] [CommRing S]
    (f : R →+* S) (hf : Function.Injective f) {n : ℕ} {M : Square3 R}
    (hM : IsMagicOfPowers n M) : IsMagicOfPowers n (M.map f)

theorem isNParker_iff_centerOne_fail_of_sign_obstruction {n : ℕ}
    (hneg : ¬ IsNthPower n (-1 : F)) :
    IsNParker F n ↔ ∀ u v : F, ¬ IsMagicOfPowers n (Square3.centerOne u v)

theorem dvd_X_pow_sub_X_of_check [DecidableEq R] {f : List R}
    {steps : List (PowStep R)} (hc : checkPow f [1] steps = true) :
    poly f ∣ (Polynomial.X ^ exponent 0 steps - Polynomial.X : Polynomial R)

theorem not_isParker_of_mem {data : List NatSquareCertificate}
    (hcheck : checkAll data = true) {c : NatSquareCertificate} (hc : c ∈ data) :
    ¬ IsParker (ZMod c.q)

theorem q3Covered_of_check {lo : ℕ} {data : List Q3Step}
    (h : Q3Step.checkFrom lo data = true) (hl : lo % 4 = 3) :
    Q3Covered lo (lo + 4 * data.length)

theorem centerOne_power_inequality_of_bound {n d q : ℕ}
    (hn : 0 < n) (hdn : d ≤ n) (hq : powerExceptionBound n < q) :
    9 * (d : ℝ) ^ 8 < (q : ℝ) - centerOneC1 d * Real.sqrt (q : ℝ)
